        Self {
            schema_version: Self::SCHEMA_VERSION,
            source,
            components,
        }
    }

    pub fn digest(&self) -> SemanticInputDigest {
        let mut transcript = CanonicalTranscript::semantic_input_v1();
        transcript.push_bytes("schema", [self.schema_version]);
